import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../styles/ManageGigs.css';

const ManageGigPostings = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [gigs, setGigs] = useState([]);
  const [filteredGigs, setFilteredGigs] = useState([]);
  const [showConfirm, setShowConfirm] = useState(false);
  const [selectedGigId, setSelectedGigId] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    fetchGigs();
  }, []);

  const fetchGigs = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/gigs');
      setGigs(response.data);
      setFilteredGigs(response.data);
    } catch (error) {
      console.error('Error fetching gigs:', error);
    }
  };

  const handleSearch = () => {
    const results = gigs.filter((gig) =>
      gig.username?.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredGigs(results);
  };

  const handleDeleteClick = (gigId) => {
    setSelectedGigId(gigId);
    setShowConfirm(true);
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`http://localhost:5000/api/gigs/${selectedGigId}`);
      setGigs((prev) => prev.filter((gig) => gig._id !== selectedGigId));
      setFilteredGigs((prev) => prev.filter((gig) => gig._id !== selectedGigId));
    } catch (error) {
      console.error("Error deleting gig:", error);
    } finally {
      setShowConfirm(false);
      setSelectedGigId(null);
    }
  };

  return (
    <div className="manage-gig-container">
      <h2 className="manage-title">Manage Gig Postings</h2>
      <input
        type="text"
        className="search-input"
        placeholder="Search by username..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <button className="search-button" onClick={handleSearch}>
        Search
      </button>

      {showConfirm && (
        <div className="modal-overlay">
          <div className="modal">
            <p>Are you sure you want to delete this gig?</p>
            <div className="modal-buttons">
              <button className="yes" onClick={confirmDelete}>Yes</button>
              <button className="no" onClick={() => setShowConfirm(false)}>No</button>
            </div>
          </div>
        </div>
      )}

      <div className="gig-list">
        {filteredGigs.length === 0 ? (
          <p className="no-gigs-message">No gigs found.</p>
        ) : (
          filteredGigs.map((gig) => (
            <div className="gig-item" key={gig._id}>
              <div className="gig-title">{gig.title}</div>
              <div className="gig-subtext">Expires: {gig.expiryDate?.split('T')[0]}</div>
              <div className="gig-actions">
                <button className="view-button" onClick={() => navigate(`/gig/${gig._id}`)}>
                  View Gig
                </button>
                <button className="delete-button" onClick={() => handleDeleteClick(gig._id)}>
                  Delete Gig
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ManageGigPostings;
